package com.pawcare.publicapi.ai;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.pawcare.publicapi.notification.NotificationService;
import com.pawcare.publicapi.web.ApiException;
import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

/** Token-authenticated bridge for a worker; no direct MySQL access is granted. */
@RestController @RequestMapping("/api/v1/internal/ai")
public class AiInternalController {
 private final JdbcTemplate db; private final ObjectMapper json; private final NotificationService notifications; private final boolean enabled; private final String token;
 public AiInternalController(JdbcTemplate db,ObjectMapper json,NotificationService notifications,@Value("${pawcare.ai.enabled:false}") boolean enabled,@Value("${pawcare.ai.worker-token:}") String token){this.db=db;this.json=json;this.notifications=notifications;this.enabled=enabled;this.token=token;}
 @GetMapping("/scoring-events") @Transactional
 public List<Map<String,Object>> events(@RequestParam(defaultValue="20") int limit,HttpServletRequest req){ auth(req); if(limit<1||limit>100)throw new ApiException(400,"limit must be 1..100"); List<Map<String,Object>> rows=db.queryForList("SELECT *, TIMESTAMPDIFF(SECOND,occurred_at,CURRENT_TIMESTAMP) AS event_age_seconds FROM ai_scoring_outbox WHERE status='PENDING' OR (status='LEASED' AND lease_until<CURRENT_TIMESTAMP) ORDER BY created_at,id LIMIT ? FOR UPDATE SKIP LOCKED",limit); for(var r:rows) db.update("UPDATE ai_scoring_outbox SET status='LEASED',lease_until=DATE_ADD(CURRENT_TIMESTAMP,INTERVAL 5 MINUTE),attempt_count=attempt_count+1 WHERE id=?",r.get("id")); return rows.stream().map(this::eventResponse).toList(); }
 @PostMapping("/scoring-events/{id}/result") @Transactional
 public Map<String,Object> result(@PathVariable long id,@RequestBody Map<String,Object> body,HttpServletRequest req){auth(req); Map<String,Object> e=one("SELECT * FROM ai_scoring_outbox WHERE id=? FOR UPDATE",id);if(e==null)throw new ApiException(404,"Scoring event not found"); if(one("SELECT id FROM ai_risk_scores WHERE outbox_event_id=?",id)!=null)return Map.of("idempotent",true); String level=text(body,"riskLevel"); BigDecimal score=number(body,"riskScore"); if(score==null||score.compareTo(BigDecimal.ZERO)<0||score.compareTo(BigDecimal.ONE)>0||!Set.of("LOW","MEDIUM","HIGH").contains(level))throw new ApiException(400,"riskScore must be 0..1 and riskLevel must be allowed"); try {db.update("INSERT INTO ai_risk_scores(outbox_event_id,aggregate_type,aggregate_id,model_name,model_version,risk_score,risk_level,explanation_summary,feature_snapshot) VALUES(?,?,?,?,?,?,?,?,CAST(? AS JSON))",id,e.get("aggregate_type"),e.get("aggregate_id"),required(body,"modelName"),required(body,"modelVersion"),score,level,truncate(text(body,"explanationSummary"),500),json.writeValueAsString(safeFeatures(body.get("featureSnapshot"))));}catch(Exception x){throw new ApiException(400,"Invalid result payload");} db.update("UPDATE ai_scoring_outbox SET status='SCORED',processed_at=CURRENT_TIMESTAMP,lease_until=NULL,last_error=NULL WHERE id=?",id); if("HIGH".equals(level)) for(var admin:db.queryForList("SELECT id FROM user_profiles WHERE role_code='ADMIN' AND is_active=1")){long pid=((Number)admin.get("id")).longValue(); notifications.notifyOnce(pid,"Cần xem xét rủi ro","Có giao dịch cần xem xét.","AI_RISK","AI_RISK_SCORE",id,"ai-risk-high:"+id);} return Map.of("idempotent",false);}
 @PostMapping("/operational-recommendations") @Transactional
 public Map<String,Object> recommendation(@RequestBody Map<String,Object> body,HttpServletRequest req){auth(req);String type=text(body,"recommendationType");if(!Set.of("INDEX","CAPACITY_FORECAST").contains(type))throw new ApiException(400,"Unsupported recommendationType");Object payload=body.get("payload");if(!(payload instanceof Map)||containsDdl(payload))throw new ApiException(400,"payload must be a safe structured recommendation, not SQL DDL");try{db.update("INSERT INTO ai_operational_recommendations(recommendation_type,subject_name,model_name,model_version,score,confidence,payload) VALUES(?,?,?,?,?,?,CAST(? AS JSON))",type,required(body,"subjectName"),required(body,"modelName"),required(body,"modelVersion"),number(body,"score"),number(body,"confidence"),json.writeValueAsString(payload));return Map.of("id",db.queryForObject("SELECT LAST_INSERT_ID()",Long.class));}catch(Exception x){throw new ApiException(400,"Invalid recommendation payload");}}
 private void auth(HttpServletRequest r){if(!enabled||token==null||token.isBlank())throw new ApiException(404,"Not found");String given=r.getHeader("X-PawCare-AI-Token");if(given==null||!MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),given.getBytes(StandardCharsets.UTF_8)))throw new ApiException(401,"Invalid AI worker token");}
 private Map<String,Object> eventResponse(Map<String,Object> row){var features=new LinkedHashMap<>(AiRiskFeatures.allow(featureMap(row.get("feature_snapshot"))));Object age=row.get("event_age_seconds");features.put("eventAgeSeconds",age instanceof Number?Math.max(0,((Number)age).longValue()):0L);return Map.of("eventId",row.get("id"),"aggregateType",row.get("aggregate_type"),"aggregateId",row.get("aggregate_id"),"eventType",row.get("event_type"),"payloadVersion",row.get("payload_version"),"features",features);}
 @SuppressWarnings("unchecked") private Map<String,Object> featureMap(Object raw){try{if(raw instanceof Map<?,?> m)return (Map<String,Object>)m;if(raw instanceof String s)return json.readValue(s,Map.class);}catch(Exception ignored){}return Map.of();}
 private Map<String,Object> one(String s,Object...a){var x=db.queryForList(s,a);return x.isEmpty()?null:x.get(0);} private String text(Map<String,Object>b,String k){return b.get(k)==null?null:String.valueOf(b.get(k)).trim();} private String required(Map<String,Object>b,String k){String x=text(b,k);if(x==null||x.isBlank())throw new ApiException(400,k+" is required");return x;} private BigDecimal number(Map<String,Object>b,String k){try{return b.get(k)==null?null:new BigDecimal(String.valueOf(b.get(k)));}catch(Exception x){throw new ApiException(400,k+" must be numeric");}} private String truncate(String v,int n){return v==null?null:v.length()>n?v.substring(0,n):v;} private Object safeFeatures(Object o){return o instanceof Map<?,?> m?AiRiskFeatures.resultAllow(m):Map.of();} private boolean containsDdl(Object o){return String.valueOf(o).toUpperCase(Locale.ROOT).matches(".*\\b(CREATE|ALTER|DROP|PARTITION)\\b.*");}
}
